                    "filter[channel]"?: string;
                    /** @description Filter by referrer: `<operator>:<value>`, where operator is `is` | `is_not` | `contains` | `not_contains`. Only applied on the `?level=` (ads-ranking) shape — the default top-N shape ignores filters. A malformed entry (missing colon, empty value) is silently skipped rather than rejected, and the dimension is not otherwise validated. */
                    "filter[referrer]"?: string;
                    /** @description Filter by campaign: `<operator>:<value>`, where operator is `is` | `is_not` | `contains` | `not_contains`. Only applied on the `?level=` (ads-ranking) shape — the default top-N shape ignores filters. A malformed entry (missing colon, empty value) is silently skipped rather than rejected, and the dimension is not otherwise validated. */
                    "filter[campaign]"?: string;
                    /** @description Filter by entry_page: `<operator>:<value>`, where operator is `is` | `is_not` | `contains` | `not_contains`. Only applied on the `?level=` (ads-ranking) shape — the default top-N shape ignores filters. A malformed entry (missing colon, empty value) is silently skipped rather than rejected, and the dimension is not otherwise validated. */
