                                    ad_set_name: string;
                                    new_ad_set_id: string | null;
                                    new_ad_set_name: string | null;
                                    /** @description The replacement is live and the ORIGINAL could not be paused — both are spending. Pause the original in Ads Manager. */
                                    double_spend_risk: boolean;
                                    double_spend_reason: string | null;
                                    source_paused: boolean;
                                    run_both: boolean;
